369	func formatDuration(ms int64) string {
370		totalSec := ms / 1000
371		switch {
372		case totalSec >= 3600:
373			h := totalSec / 3600
374			m := (totalSec % 3600) / 60
375			return fmt.Sprintf("%dh %dm", h, m)
376		case totalSec >= 60:
377			m := totalSec / 60
378			s := totalSec % 60
379			return fmt.Sprintf("%dm %ds", m, s)
380		default:
381			return fmt.Sprintf("%ds", totalSec)
382		}
